import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"常见使用案例","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/guides/use-cases.md","filePath":"zh/kimi-code-cli/guides/use-cases.md"}`),a={name:`kimi-code-cli/guides/use-cases.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="常见使用案例" tabindex="-1">常见使用案例 <a class="header-anchor" href="#常见使用案例" aria-label="Permalink to “常见使用案例”">​</a></h1><p>本页收录 Kimi Code CLI 的典型使用场景和配套的 prompt 示例，可以直接复制使用或按需修改。</p><h2 id="理解陌生项目" tabindex="-1">理解陌生项目 <a class="header-anchor" href="#理解陌生项目" aria-label="Permalink to “理解陌生项目”">​</a></h2><p>接手陌生仓库时，建议先用 <code>kimi --plan</code> 或按 <code>Shift-Tab</code> 进入 Plan 模式，让 Agent 先输出调研计划再动手，避免读到一半就开始改文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>帮我梳理这个仓库的整体架构。重点说清楚：</span></span>
<span class="line"><span>1. 入口在哪里，启动后做了什么</span></span>
<span class="line"><span>2. 主要模块之间的依赖关系</span></span>
<span class="line"><span>3. 配置和数据的加载流程</span></span>
<span class="line"><span>最后画一张简单的模块关系图。</span></span></code></pre></div><p>也可以聚焦到具体问题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>src/runtime 下的 event loop 是怎么工作的？事件从哪里产生、又被谁消费？</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这个项目里「权限审批」是怎么实现的？涉及哪些文件，关键类型是什么？</span></span></code></pre></div><p>大型调研可以让主 Agent 派发<strong>子 Agent</strong> 并行处理子任务，详见 <a href="/code/docs/kimi-code-cli/customization/agents.html">Agent 与子 Agent</a>。</p><h2 id="实现新功能" tabindex="-1">实现新功能 <a class="header-anchor" href="#实现新功能" aria-label="Permalink to “实现新功能”">​</a></h2><p>描述清楚需求和验收标准，复杂需求建议先用 Plan 模式确认方案再执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>在 src/utils 下新增一个 retry 工具：</span></span>
<span class="line"><span>- 函数签名 retry&lt;T&gt;(fn: () =&gt; Promise&lt;T&gt;, options): Promise&lt;T&gt;</span></span>
<span class="line"><span>- 支持 maxAttempts、initialDelayMs、backoffFactor 三个选项</span></span>
<span class="line"><span>- 失败时抛出最后一次的错误</span></span>
<span class="line"><span>- 补一组单元测试覆盖成功、重试后成功、全部失败三种情况</span></span></code></pre></div><p>如果结果不满意，直接描述改动即可，无需手动编辑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>backoff 算了一个固定值，我希望加一点抖动，避免雷击效应。改一下并更新测试。</span></span></code></pre></div><h2 id="修复-bug" tabindex="-1">修复 bug <a class="header-anchor" href="#修复-bug" aria-label="Permalink to “修复 bug”">​</a></h2><p>把现象、复现条件和期望行为一次性说清楚，可以省去来回澄清的时间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>跑 npm test 时偶发地报这个错：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  TypeError: Cannot read properties of undefined (reading &#39;id&#39;)</span></span>
<span class="line"><span>      at SessionStore.update (src/session/store.ts:142:18)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>只在并发触发多个 update 的用例里出现。帮我定位原因并修复，最后跑一次完整测试确认。</span></span></code></pre></div><p>不确定原因时，先让 Agent 调查再动手：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>用户反馈：登录成功后第一次刷新页面会回到登录页，再刷一次就正常了。先帮我排查可能的原因，列出几个最可疑的位置，等我确认方向后再动手改。</span></span></code></pre></div><p>纯机械任务可以直接放手：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>跑一遍测试，失败的用例都修掉，跑完再跑一次确认全绿。</span></span></code></pre></div><h2 id="写测试与重构" tabindex="-1">写测试与重构 <a class="header-anchor" href="#写测试与重构" aria-label="Permalink to “写测试与重构”">​</a></h2><p>边界清晰、验收标准明确的任务特别适合交给 Agent：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>src/parser/markdown.ts 目前几乎没有测试。请补一组单元测试，覆盖正常段落、嵌套列表、代码块、表格、引用块和混合场景。用项目里已有的测试风格。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>把 src/handlers 下重复的「读 body → 校验 → 写日志 → 返回」逻辑抽成一个中间件。改完跑一遍测试，保证现有行为不变。</span></span></code></pre></div><p>多文件重构建议先用 Plan 模式确认方案，可用 <code>/fork</code> 派生一个试验分支，不满意直接切回原会话。</p><h2 id="一次性脚本与自动化任务" tabindex="-1">一次性脚本与自动化任务 <a class="header-anchor" href="#一次性脚本与自动化任务" aria-label="Permalink to “一次性脚本与自动化任务”">​</a></h2><p>批量改文件、跑统计、调研对比等任务用一段 prompt 就能完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>把 src 目录下所有 .js 文件里的 var 声明改成 const 或 let，能用 const 的优先用 const。改完跑一次 lint 确认。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>分析 logs/ 下最近 7 天的访问日志，按接口路径统计调用次数、p50 和 p99 响应时间，结果输出成一个 markdown 表格。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>帮我调研一下 TypeScript 里几种主流的依赖注入方案（tsyringe、inversify、awilix），从 API 风格、装饰器依赖、运行时开销三个维度对比，给一份不超过一页的建议。</span></span></code></pre></div><p>对于确定安全的批处理任务，可以用 <code>--yolo</code> 或 <code>/yolo</code> 跳过审批，也可以在<a href="/code/docs/kimi-code-cli/configuration/config-files.html#permission">配置文件</a>里给特定工具预置白名单规则。</p><h2 id="定时任务与提醒" tabindex="-1">定时任务与提醒 <a class="header-anchor" href="#定时任务与提醒" aria-label="Permalink to “定时任务与提醒”">​</a></h2><p>在交互式会话内，可以让 Agent 设置一次性提醒或按周期运行的任务。Agent 会生成本地时区的 cron 表达式，并在触发时把 prompt 重新注入到同一个会话中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下午 2:30 提醒我去查一下部署。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>每个工作日上午 9 点，帮我汇总最近的 CI 失败情况。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>每小时巡检一次生产环境的健康端点，看到异常就告诉我。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>大约 10 分钟之后再回来，确认一下构建是否结束。</span></span></code></pre></div><p>定时计划绑定在会话内：关掉终端没关系，用 <code>kimi --session</code> 恢复同一个会话时会重新加载并继续触发；但它们不会带入全新的会话。周期任务在 7 天后会自动过期——Agent 会在最后一次触发时收到 <code>stale</code> 提示，可根据你之前的指示决定结束还是续期。</p><p>想查看当前有哪些挂起的任务，直接问 Agent 即可（它会调用只读的 <code>CronList</code> 工具）；要取消某个任务，让 Agent 删除它或引用对应的 8 位 id。完整工具说明见<a href="/code/docs/kimi-code-cli/reference/tools.html#定时任务">定时任务</a>；整体关停开关是 <code>KIMI_DISABLE_CRON=1</code>。</p><h2 id="生成与维护文档" tabindex="-1">生成与维护文档 <a class="header-anchor" href="#生成与维护文档" aria-label="Permalink to “生成与维护文档”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我刚改了 src/auth/login.ts 的接口签名，把对应的 JSDoc、README 里的示例代码、还有 docs/zh/guides 下提到这个接口的段落都同步更新一遍。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>src/api 下所有公开函数里，凡是没有 docstring 的都补上文档注释，风格参考已有的注释。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>根据 src/cli 下的命令实现，生成一份命令参考的草稿，列出每个子命令、参数和默认值，放到 docs/zh/reference 下我后续审阅。</span></span></code></pre></div><p>需要留档或复盘时，用 <code>kimi export &lt;sessionId&gt;</code> 打包为 ZIP，或在 TUI 中用 <code>/export-md</code> 导出为可读的 Markdown 对话记录。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/customization/agents.html">Agent 与子 Agent</a> — 如何让 Agent 派发子任务并行处理</li><li><a href="/code/docs/kimi-code-cli/customization/hooks.html">Hooks</a> — 在任务完成等节点触发本地脚本</li><li><a href="/code/docs/kimi-code-cli/reference/tools.html">内置工具</a> — Agent 可调用的全部工具参考</li></ul>`,47)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};